SELECT "product_product"."id", "product_product"."title", "product_product"."slug", "product_product"."description", "product_product"."minimum_order", "product_product"."related_product_id", "product_product"."product_type", "product_product"."category_id", "product_product"."base_price", "product_product"."status", "product_product"."stock", "product_product"."created_at", "product_product"."updated_at", MIN("user_panel_sellerproduct"."price") AS "min_price", SUM(T3."available_count") AS "sell_count" FROM "product_product" INNER JOIN "user_panel_sellerproduct" ON ("product_product"."id" = "user_panel_sellerproduct"."product_id") INNER JOIN "user_panel_sellerproduct" T3 ON ("product_product"."id" = T3."product_id") WHERE "user_panel_sellerproduct"."available_count" > 0 GROUP BY "product_product"."id", "product_product"."title", "product_product"."slug", "product_product"."description", "product_product"."minimum_order", "product_product"."related_product_id", "product_product"."product_type", "product_product"."category_id", "product_product"."base_price", "product_product"."status", "product_product"."stock", "product_product"."created_at", "product_product"."updated_at", T3."price" HAVING T3."price" = (MIN("user_panel_sellerproduct"."price"))